SELECT CASE WHEN suppliers.rating >= 4.1 THEN 'high' WHEN suppliers.rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS num_products, MAX(products.stock_qty) - MIN(products.stock_qty) AS stock_qty_range FROM products LEFT JOIN suppliers ON products.supplier_id = suppliers.id GROUP BY CASE WHEN suppliers.rating >= 4.1 THEN 'high' WHEN suppliers.rating >= 1.5 THEN 'mid' ELSE 'low' END;
